mapper.select:
SELECT COUNT(0) FROM directory WHERE owner_id = #{ownerId} AND fullpath = #{fullpath}
AND deleted_at IS NULL
AND deleted_at IS NOT NULL

SELECT id AS id, owner_id AS ownerId, fullpath AS fullpath, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt, DATE_FORMAT(deleted_at, '%Y-%m-%d %H:%i:%s') AS deletedAt FROM directory WHERE owner_id = #{ownerId} AND (fullpath = #{fullpath} OR fullpath LIKE CONCAT(#{fullpath}, '/%'))
AND deleted_at IS NULL
AND deleted_at IS NOT NULL
ORDER BY ${sort}
LIMIT #{pageSize} OFFSET #{current}

SELECT fullname FROM file_info WHERE owner_id = #{ownerId} AND ( JSON_CONTAINS(JSON_ARRAY(${equalFullpaths}), CONCAT('["', directory, '"]'))
OR
directory LIKE #{likeFullpath}
)

mapper.delete:
DELETE FROM
    directory
WHERE
    id != 'TEMP'
    AND owner_id = #{ownerId}
    AND (
        JSON_CONTAINS(JSON_ARRAY(${equalFullpaths}), CONCAT('["', fullpath, '"]'))

        OR

            fullpath LIKE #{likeFullpath}


    )
